<?php
require_once __DIR__.'/NotificationService.php';
final class SubmissionNotifications {
    private static function receipt(NotificationService $service,int $uid,string $title,string $message,string $table,int $id,string $key,string $type='success'):void {if(!$service->notify($uid,$title,$message,$type,$table,$id,true,null,null,$key))throw new RuntimeException('The submission notification could not be recorded. Please try again.');}
    public static function pds(PDO $db,int $uid,int $version,string $year,bool $review):void {
        $s=new NotificationService($db);$key='pds_version:'.$version;$title=$review?'Annual PDS submitted':'PDS saved';$message=($review?'Your annual PDS review was submitted':'Your personal data sheet was saved').($year!==''?' for school year '.$year:'').'.';self::receipt($s,$uid,$title,$message,'pds_versions',$version,$key);
        $s->staff(['admin'],$review?'Annual PDS ready for review':'Student PDS updated','A student personal data sheet '.($review?'was submitted':'was saved').($year!==''?' for school year '.$year:'').'. Sign in to review the record.','pds_versions',$version,$key);
    }
    public static function paperPds(PDO $db,int $owner,int $version):void {self::receipt(new NotificationService($db),$owner,'Paper PDS entered by Guidance','The Guidance Office has entered your paper personal data sheet into your account. Sign in to review the information and contact Guidance if a correction is needed.','pds_versions',$version,'paper-pds:'.$version);}
    public static function survey(PDO $db,int $uid,string $kind,int $id,string $year,bool $update):void {
        $map=['mi'=>['multiple_intelligence_survey','Multiple Intelligence'],'ls'=>['learning_style_inventory','Learning Style'],'ls_intermediate'=>['learning_style_inventory_intermediate','Learning Style (Intermediate)']];if(!isset($map[$kind]))throw new InvalidArgumentException('Invalid survey notification.');[$table,$label]=$map[$kind];$key='survey:'.$kind.':'.$id.':'.bin2hex(random_bytes(12));$s=new NotificationService($db);
        self::receipt($s,$uid,$update?'Survey updated':'Survey submitted','Your '.$label.' survey '.($update?'was updated':'was submitted').' for school year '.$year.'.',$table,$id,$key);
        $s->staff(['admin','guidance_advocate'],'Student survey '.($update?'updated':'submitted'),'A '.$label.' survey is ready for review for school year '.$year.'.',$table,$id,$key);
    }
    public static function appointment(PDO $db,string $kind,int $id):void {
        $exam=$kind==='exam';$table=$exam?'entrance_exam_appointments':'counseling_appointments';$q=$db->prepare('SELECT user_id,'.($exam?'preferred_date AS day,preferred_time AS time':'appointment_date AS day,appointment_time AS time').' FROM '.$table.' WHERE id=?');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('Appointment unavailable.');
        $label=$exam?'entrance exam':'counseling';$when=date('M j, Y',strtotime($r['day'])).' at '.date('g:i A',strtotime($r['time']));$key=($exam?'exam':'counseling').'_booking:'.$id;$s=new NotificationService($db);
        if($exam){$record=self::examRecord($db,$id);$message="Your entrance exam application has been received and your exam session is confirmed.\n\nSchedule: ".self::examSchedule($record)."\n\nPlease follow the Guidance Office's instructions for your examination. Sign in to view your application and any further updates.";self::receipt($s,(int)$r['user_id'],'Entrance exam application confirmed',$message,$table,$id,$key,'appointment_confirmed');}else self::receipt($s,(int)$r['user_id'],'Appointment confirmed','Your '.$label.' appointment is confirmed for '.$when.'.',$table,$id,$key,'appointment_confirmed');$s->staff(['admin','guidance_advocate'],'New '.($exam?'exam':'counseling').' appointment','A new '.$label.' appointment is scheduled for '.$when.'. Sign in to view the record.',$table,$id,$key);
    }
    public static function change(PDO $db,string $kind,int $id,string $event):void {
        $exam=$kind==='exam';$table=$exam?'entrance_exam_appointments':'counseling_appointments';$q=$db->prepare('SELECT user_id,'.($exam?'preferred_date AS day,preferred_time AS time':'appointment_date AS day,appointment_time AS time').' FROM '.$table.' WHERE id=?');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)return;
        $labels=['confirmed'=>'confirmed','cancelled'=>'cancelled','completed'=>'completed','missed'=>'marked as missed','in_progress'=>'started','rescheduled'=>'rescheduled','followup'=>'scheduled for follow-up','awaiting_results'=>'recorded as attended'];$label=$exam?'entrance exam':'counseling';$title=$event==='followup'?'Follow-up scheduled':'Appointment update';$message='Your '.$label.' appointment was '.($labels[$event]??'updated').'.';if($r['day']&&$r['time'])$message.=' Schedule: '.date('M j, Y',strtotime($r['day'])).' at '.date('g:i A',strtotime($r['time'])).'.';
        if($exam&&$event==='rescheduled'){$record=self::examRecord($db,$id);$title='Your entrance exam has been rescheduled';$message=!empty($record['rescheduled_from_id'])?'Your previous exam was not recorded as completed. Your application has been moved automatically to the next available scheduled exam.':'The Guidance Office has updated your entrance exam schedule.';
            if(!empty($record['rescheduled_from_id'])){$q=$db->prepare('SELECT * FROM entrance_exam_appointments WHERE id=? AND user_id=?');$q->execute([$record['rescheduled_from_id'],$record['user_id']]);if($previous=$q->fetch(PDO::FETCH_ASSOC))$message.="\n\nPrevious schedule: ".self::examSchedule($previous);}
            $message.="\n\nNew schedule: ".self::examSchedule($record)."\n\nYour application remains active. Please attend the new session and check your application for further instructions. Contact the Guidance Office if you need assistance.";}
        $key=$kind.':'.$id.':'.$event.':'.bin2hex(random_bytes(12));$service=new NotificationService($db);$type=in_array('appointment_'.$event,Notification::TYPES,true)?'appointment_'.$event:'info';self::receipt($service,(int)$r['user_id'],$title,$message,$table,$id,$key,$type);
        if($event!=='in_progress')$service->staff(['admin','guidance_advocate'],'Appointment '.($event==='followup'?'follow-up':'updated'),'A '.$label.' appointment was '.($labels[$event]??'updated').'. Sign in to review its schedule and status.',$table,$id,$key);
    }
    private static function examRecord(PDO $db,int $id):array {
        $q=$db->prepare('SELECT * FROM entrance_exam_appointments WHERE id=?');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('Exam application unavailable.');return $r;
    }
    private static function examSchedule(array $r):string {
        $zone=new DateTimeZone('Asia/Manila');$value=($r['preferred_date']??'').' '.($r['preferred_time']??'');$start=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$value,$zone);if(!$start||$start->format('Y-m-d H:i:s')!==$value)return 'Please sign in to view the confirmed schedule.';
        $when=$start->format('l, F j, Y').' at '.$start->format('g:i A');$endValue=$r['slot_end_at']??'';$end=$endValue?DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$endValue,$zone):false;if($end&&$end->format('Y-m-d H:i:s')===$endValue&&$end>$start)$when.=' to '.($end->format('Y-m-d')===$start->format('Y-m-d')?$end->format('g:i A'):$end->format('F j, Y').' at '.$end->format('g:i A'));return $when.' (Philippine time).';
    }
    public static function examineeAccount(PDO $db,int $uid):void {
        $q=$db->prepare("SELECT id FROM users WHERE id=? AND role='examinee'");$q->execute([$uid]);if(!$q->fetchColumn())throw new RuntimeException('Examinee account unavailable.');
        $title='Your examinee account is ready';$message="Welcome to SRCB Guidance. Your examinee account has been created.\n\nNext step: sign in with your registered email and choose an available entrance exam session. We will email you when your exam application is confirmed, your schedule changes, or your results are released.\n\nStudent enrollment will be processed by the school after the required verification.";
        if(!(new NotificationService($db))->notify($uid,$title,$message,'success',null,null,true,null,MailTemplate::render($title,$message,'entrance_exam_appointments','booking'),'examinee-account:'.$uid))throw new RuntimeException('The account confirmation could not be queued.');
    }
    /** Read only released decisions; never infer Passed from a score or qualification. */
    public static function examResults(PDO $db,int $id):void {
        $r=self::examRecord($db,$id);if($r['status']!=='completed'||!in_array($r['exam_result'],['passed','failed'],true))throw new RuntimeException('Release a recorded Passed or Failed result before sending a results notice.');
        $passed=$r['exam_result']==='passed';$app=require __DIR__.'/../../config/app.php';$school=$app['school_name'];
        if($passed){$title='You passed your entrance exam';$message="Congratulations! Your released entrance exam result is Passed.\n\nNext step: please visit ".$school." to verify your enrollment and confirm the required documents and next steps with the school. Your enrollment will be finalized after the school verifies your requirements.\n\nYou can review your released result in the examinee portal. Keep using your current account; the school will update it to a student account when your enrollment is processed.";}
        else{$title='Your entrance exam result is available';$message="Your entrance exam result has been released.\n\nRecorded result: Failed.\n\nPlease sign in to review your result and contact the Guidance Office for assistance with your next steps.";}
        $fields=['exam_result','exam_date','olsat_level','olsat_form','verbal_abilities_score','verbal_comprehension_score','verbal_reasoning_score','nonverbal_abilities_score','figural_reasoning_score','quantitative_reasoning_score','total_score','total_items','stanine_score','verbal_stanine','nonverbal_stanine','interpretation','verbal_interpretation','nonverbal_interpretation','qualified_grade','academic_strand','qualified_program','school_year'];$released=[];foreach($fields as $field)$released[$field]=$r[$field]??null;$key='exam-results:'.$id.':'.substr(hash('sha256',json_encode($released)),0,40);
        if(!(new NotificationService($db))->notify((int)$r['user_id'],$title,$message,$passed?'success':'info','entrance_exam_appointments',$id,true,null,MailTemplate::render($title,$message,'entrance_exam_appointments','results'),$key))throw new RuntimeException('The results notification could not be saved.');
    }

    public static function assigned(PDO $db,int $id,int $assignee):void {
        $q=$db->prepare('SELECT user_id FROM counseling_appointments WHERE id=?');$q->execute([$id]);$owner=(int)$q->fetchColumn();if(!$owner)return;$s=new NotificationService($db);$key='assignment:'.$id.':'.bin2hex(random_bytes(12));self::receipt($s,$owner,'Counselor assigned','A counselor has been assigned to your appointment. Sign in to view the details.','counseling_appointments',$id,$key);self::receipt($s,$assignee,'New counseling assignment','You have been assigned a counseling appointment. Sign in to review its schedule.','counseling_appointments',$id,$key,'advocate_assignment');
    }
}
